// =============================================
// CHARACTER MEMORY - Central character store
// All prompts will reference these definitions
// to ensure visual consistency across videos.
// =============================================
const characters = {
  main: {
    name: 'Leo',
    age: 3,
    role: 'toddler protagonist',
    appearance: {
      hair: 'soft blonde hair, lightly tousled, slightly curly at the tips',
      eyes: 'bright sky-blue eyes, large and expressive',
      face: 'round chubby cheeks, fair skin with a light pink blush, small button nose, tiny rosy lips',
      build: 'small toddler stature, about 95cm tall, soft baby-fat proportions',
      outfit: 'pastel blue cotton t-shirt, beige overall shorts, white sneakers with velcro straps',
      personality: 'curious, playful, kind, gentle laugh'
    },
    voice: 'soft toddler voice, light giggles, simple short sentences'
  },
  mother: {
    name: 'Mom (Sarah)',
    appearance: 'warm-eyed woman in late 20s, long wavy chestnut-brown hair tied loosely, soft smile, light freckles, wearing a cream knit cardigan over a white tee and light denim jeans',
    voice: 'gentle, warm, calm tone'
  },
  father: {
    name: 'Dad (Daniel)',
    appearance: 'friendly man in early 30s, short dark-brown hair, light stubble, kind hazel eyes, navy henley shirt, dark grey chinos, casual brown sneakers',
    voice: 'warm, deep, playful'
  },
  dog: {
    name: 'Max',
    breed: 'Golden Retriever',
    appearance: 'large fluffy golden coat, friendly soft brown eyes, pink tongue, red collar with a small bone-shaped tag, wagging tail, gentle and protective',
    voice: 'soft barks, happy panting'
  }
};

// Niches the channel rotates through
const niches = [
  'toddler stories',
  'family stories',
  'funny situations',
  'emotional stories',
  'animal friendships',
  'school life',
  'road trips',
  'market adventures'
];

// Pick a niche pseudo-randomly weighted by hour-of-day
const hour = new Date().getHours();
const niche = niches[(hour + Math.floor(Math.random() * niches.length)) % niches.length];

return [{
  json: {
    characters,
    niches,
    selectedNiche: niche,
    runId: `run_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    runTimestamp: new Date().toISOString()
  }
}];

// Aggregate previous idea titles for de-duplication
const memory = $('Load Character Memory').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.title);
const existingTitles = rows.map(r => String(r.title).toLowerCase().trim());

return [{
  json: {
    ...memory,
    existingTitles,
    existingIdeasCount: existingTitles.length
  }
}];

