// Parse Gemini idea response and check for duplicates
const raw = $input.first().json;
const memory = $('Prepare Dedup Context').first().json;

let ideaText = '';
try {
  ideaText = raw.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Gemini returned no candidates: ' + JSON.stringify(raw).slice(0, 500));
}

let idea;
try {
  idea = JSON.parse(ideaText);
} catch (e) {
  // Try to extract JSON block
  const m = ideaText.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Could not parse idea JSON: ' + ideaText.slice(0, 300));
  idea = JSON.parse(m[0]);
}

const lowerTitle = String(idea.title || '').toLowerCase().trim();
const isDuplicate = memory.existingTitles.some(t =>
  t === lowerTitle || (t.length > 8 && lowerTitle.includes(t)) || (lowerTitle.length > 8 && t.includes(lowerTitle))
);

if (isDuplicate) {
  throw new Error(`Duplicate idea detected: "${idea.title}". Aborting this run.`);
}

return [{
  json: {
    ...memory,
    idea,
    ideaTitle: idea.title,
    ideaLogline: idea.logline,
    ideaHook: idea.hook,
    ideaBeats: idea.story_beats,
    ideaSetting: idea.setting,
    ideaEmotion: idea.emotion
  }
}];

