const raw = $input.first().json;
const prev = $('Parse + Dedup Check').first().json;
let text = '';
try { text = raw.candidates[0].content.parts[0].text; } catch (e) { throw new Error('Gemini prompt response invalid: ' + JSON.stringify(raw).slice(0, 400)); }
let promptObj;
try { promptObj = JSON.parse(text); } catch (e) {
  const m = text.match(/\{[\s\S]*\}/); if (!m) throw new Error('Bad prompt JSON');
  promptObj = JSON.parse(m[0]);
}
return [{ json: { ...prev, veoPrompt: promptObj.veo_prompt, negativePrompt: promptObj.negative_prompt, aspectRatio: promptObj.aspect_ratio || '9:16', durationSeconds: promptObj.duration_seconds || 8 } }];

const submit = $input.first().json;
const prev = $('Parse Veo Prompt').first().json;
const opName = submit.name;
if (!opName) throw new Error('Veo did not return an operation name. Resp: ' + JSON.stringify(submit).slice(0, 400));
return [{ json: { ...prev, veoOperation: opName, pollAttempt: 0 } }];

const r = $input.first().json;
const prev = $('Init Poll State').first().json;
const attempt = (prev.pollAttempt || 0) + 1;
const maxAttempts = parseInt($env.VEO_MAX_POLL_ATTEMPTS || '40');

if (r.done === true) {
  if (r.error) {
    throw new Error('Veo failed: ' + JSON.stringify(r.error));
  }
  // Success - extract video URI
  const videos = (r.response && (r.response.videos || (r.response.predictions && r.response.predictions[0] && r.response.predictions[0].videos))) || [];
  const first = videos[0] || {};
  const gcsUri = first.gcsUri || first.uri || (r.response && r.response.generatedVideos && r.response.generatedVideos[0] && r.response.generatedVideos[0].video && r.response.generatedVideos[0].video.uri);
  if (!gcsUri) throw new Error('Veo done but no video URI: ' + JSON.stringify(r).slice(0, 600));
  return [{ json: { ...prev, pollAttempt: attempt, veoDone: true, gcsUri, videoMime: first.mimeType || 'video/mp4' } }];
}

if (attempt >= maxAttempts) {
  throw new Error(`Veo polling timed out after ${attempt} attempts`);
}

return [{ json: { ...prev, pollAttempt: attempt, veoDone: false } }];

// Convert gs:// URI to authenticated download URL
const data = $input.first().json;
const gcs = data.gcsUri;
if (!gcs.startsWith('gs://')) throw new Error('Unexpected URI: ' + gcs);
const withoutScheme = gcs.replace('gs://', '');
const slash = withoutScheme.indexOf('/');
const bucket = withoutScheme.slice(0, slash);
const objectPath = withoutScheme.slice(slash + 1);
const encoded = encodeURIComponent(objectPath);
const downloadUrl = `https://storage.googleapis.com/storage/v1/b/${bucket}/o/${encoded}?alt=media`;
return [{ json: { ...data, gcsBucket: bucket, gcsObject: objectPath, downloadUrl } }];

