const raw = $input.first().json;
const videoBin = $('Download Video from GCS').first();
const prev = $('Build GCS Download URL').first().json;
let text = ''; try { text = raw.candidates[0].content.parts[0].text; } catch(e){ throw new Error('Meta resp invalid'); }
let meta; try { meta = JSON.parse(text); } catch(e){ const m = text.match(/\{[\s\S]*\}/); meta = JSON.parse(m[0]); }
const hashtags = (meta.hashtags || []).map(t => t.startsWith('#') ? t : '#' + t);
return [{ json: { ...prev, ytTitle: meta.yt_title, ytDescription: meta.yt_description, fbCaption: meta.fb_caption, hashtags, hashtagString: hashtags.join(' ') }, binary: videoBin.binary }];

const drive = $input.first().json;
const prev = $('Parse Metadata').first().json;
const videoBin = $('Download Video from GCS').first();
const driveUrl = drive.webViewLink || `https://drive.google.com/file/d/${drive.id}/view`;
return [{ json: { ...prev, driveFileId: drive.id, driveUrl }, binary: videoBin.binary }];

// Aggregate upload results from both branches
const merged = $('Merge Drive Info').first().json;
let ytUrl = '', ytId = '', ytStatus = 'failed';
try {
  const yt = $('YouTube: Upload Short').first().json;
  ytId = yt.id || '';
  ytUrl = ytId ? `https://youtube.com/shorts/${ytId}` : '';
  ytStatus = ytId ? 'scheduled' : 'failed';
} catch (e) { ytStatus = 'failed'; }
let fbId = '', fbUrl = '', fbStatus = 'failed';
try {
  const fb = $('Facebook: Publish Reel').first().json;
  fbId = fb.id || $('Facebook: Init Reel Upload').first().json.video_id || '';
  fbUrl = fbId ? `https://www.facebook.com/reel/${fbId}` : '';
  fbStatus = (fb.success === true || fbId) ? 'scheduled' : 'failed';
} catch (e) { fbStatus = 'failed'; }
return [{ json: { ...merged, ytId, ytUrl, ytStatus, fbId, fbUrl, fbStatus, finalStatus: (ytStatus === 'scheduled' || fbStatus === 'scheduled') ? 'published' : 'partial_failure', completedAt: new Date().toISOString() } }];

// Collect any error from upstream onError outputs into a normalized payload
const errors = $input.all().map(i => i.json);
const err = errors[0] || {};
return [{
  json: {
    runId: err.runId || ($('Load Character Memory').first()?.json?.runId) || `unknown_${Date.now()}`,
    stage: err.stage || 'unknown',
    error: err.error || err.message || JSON.stringify(err).slice(0, 500),
    timestamp: new Date().toISOString()
  }
}];
